SELECT trading_date,total_sales,net_sales,gst,authoritative_source,resolution_type FROM resolved_daily_sales WHERE trading_date BETWEEN '2026-10-26' AND '2026-11-01' ORDER BY 1;
SELECT trading_date,source_system,total_sales,net_total,gst_total FROM canonical_daily_sales WHERE superseded_at IS NULL AND trading_date BETWEEN '2026-10-26' AND '2026-11-01' ORDER BY 1,2;
SELECT trading_date,source_system,count(*) rows,sum(quantity_sold) quantity,sum(amount) gross FROM canonical_product_sales WHERE superseded_at IS NULL AND trading_date BETWEEN '2026-10-26' AND '2026-11-01' GROUP BY 1,2 ORDER BY 1,2;
SELECT trading_date,count(*) negative_lines,sum(amount) negative_gross FROM resolved_sale_line WHERE amount<0 AND trading_date BETWEEN '2026-10-26' AND '2026-11-01' GROUP BY 1 ORDER BY 1;
SELECT coalesce(s.trading_date,l.trading_date) trading_date,coalesce(s.product_name_key,l.name) product_name_key,sum(s.amount) resolved_gross,sum(l.gross) receipt_final_gross,sum(l.net) receipt_final_net FROM resolved_product_sales s FULL JOIN (SELECT trading_date,regexp_replace(btrim(regexp_replace(lower(item_name),'[^a-z0-9]+',' ','g')),'^new ','') name,sum(amount) gross,sum((adjustment->>'finalExTax')::numeric) net FROM resolved_sale_line WHERE trading_date BETWEEN '2026-10-26' AND '2026-11-01' GROUP BY 1,2) l ON s.trading_date=l.trading_date AND s.product_name_key=l.name WHERE coalesce(s.trading_date,l.trading_date) BETWEEN '2026-10-26' AND '2026-11-01' AND s.amount IS DISTINCT FROM l.gross GROUP BY 1,2 ORDER BY abs(coalesce(sum(s.amount),0)-coalesce(sum(l.gross),0)) DESC LIMIT 35;
